// Reject bad payloads early so nothing half-written reaches the CRM.
const b = $input.first().json.body || {};
const missing = ['contact_email', 'transcript'].filter(k => !b[k] || String(b[k]).trim() === '');
let error = null;
if (missing.length) error = 'Missing field: ' + missing.join(', ');
else if (String(b.transcript).length < 200) error = 'Transcript too short to analyse';
return [{ json: {
  ok: !error, error,
  call_id: b.call_id || 'call-' + Date.now(),
  contact_email: String(b.contact_email || '').trim().toLowerCase(),
  rep: b.rep || 'Unknown rep',
  source: b.source || 'unknown',
  recorded_at: b.recorded_at || new Date().toISOString(),
  duration_seconds: b.duration_seconds || null,
  transcript: String(b.transcript || '').slice(0, 60000),
} }];

// A contact can have several deals: use the most recently updated open one.
const deals = $input.first().json.results || [];
const open = deals.filter(d => d.properties.hs_is_closed !== 'true');
const pool = open.length ? open : deals;
pool.sort((a, b) => String(b.properties.hs_lastmodifieddate).localeCompare(String(a.properties.hs_lastmodifieddate)));
const deal = pool[0];
const contact = $('Find contact in HubSpot').first().json.results[0];
return [{ json: {
  call: $('Check payload').first().json,
  contact: { id: contact.id, name: [contact.properties.firstname, contact.properties.lastname].filter(Boolean).join(' '), email: contact.properties.email },
  deal: { id: deal.id, name: deal.properties.dealname, stage: deal.properties.dealstage, amount: deal.properties.amount },
} }];

