// Turn the AI answer into CRM fields, with guard rails:
// the stage only moves FORWARD, only when the AI is confident, and AI never closes a deal.
// Pipeline stage ids and the confidence threshold come from the Config node.
const cfg = $('Config').first().json;
const STAGES = String(cfg.stage_order).split(',').map(s => s.trim()).filter(Boolean);
const MIN_CONFIDENCE = Number(cfg.min_stage_confidence) || 0.75;
const ctx = $('Pick the open deal').first().json;
let raw = $input.first().json.choices?.[0]?.message?.content || '{}';
raw = raw.replace(/^\s*```(json)?/i, '').replace(/```\s*$/, '');
const ai = JSON.parse(raw);
const clean = s => String(s ?? '').replace(/\u2014|\u2013/g, ', ').trim();

const current = STAGES.indexOf(ctx.deal.stage);
const suggested = STAGES.indexOf(ai.suggested_stage);
const confidence = Math.max(0, Math.min(1, Number(ai.stage_confidence) || 0));
const isClosing = ['closedwon', 'closedlost'].includes(ai.suggested_stage);
const moveStage = suggested > current && confidence >= MIN_CONFIDENCE && !isClosing;

const steps = (ai.next_steps || []).map(s => '- ' + clean(s.what) + (s.who ? ' (' + clean(s.who) + ')' : '') + (s.due ? ', due ' + clean(s.due) : '')).join('\n') || 'not mentioned';
const objections = (ai.objections || []).map(o => '- ' + clean(o)).join('\n') || 'none raised';
const bs = ai.buying_signals || {};
const signals = ['Budget: ' + clean(bs.budget), 'Timeline: ' + clean(bs.timeline), 'Decision maker: ' + clean(bs.decision_maker), 'Other: ' + clean(bs.other)].join('\n');

const properties = {
  ai_call_summary: clean(ai.summary),
  ai_next_steps: steps,
  ai_objections: objections,
  ai_buying_signals: signals,
  ai_call_sentiment: ['positive', 'neutral', 'negative'].includes(ai.sentiment) ? ai.sentiment : 'neutral',
  ai_suggested_stage: suggested >= 0 ? ai.suggested_stage : 'unknown',
  ai_stage_confidence: Math.round(confidence * 100) / 100,
  ai_last_call_at: new Date(ctx.call.recorded_at).getTime(),
};
if (moveStage) properties.dealstage = ai.suggested_stage;

const esc = s => clean(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/\n/g, '<br>');
const noteHtml = '<p><strong>AI call report</strong> (' + esc(ctx.call.source) + ', ' + Math.round((ctx.call.duration_seconds || 0) / 60) + ' min, rep ' + esc(ctx.call.rep) + ')</p>'
  + '<p>' + esc(ai.summary) + '</p>'
  + '<p><strong>Next steps</strong><br>' + esc(steps) + '</p>'
  + '<p><strong>Objections</strong><br>' + esc(objections) + '</p>'
  + '<p><strong>Stage</strong>: ' + (moveStage ? 'moved to ' + esc(ai.suggested_stage) : 'unchanged (' + esc(ctx.deal.stage) + '), AI suggested ' + esc(ai.suggested_stage) + ' at ' + Math.round(confidence * 100) + '% confidence') + '. ' + esc(ai.stage_reason) + '</p>';

return [{ json: { ...ctx, properties, noteHtml, stage_moved: moveStage, stage_reason: clean(ai.stage_reason) } }];
